import React from "react";
import { Pagination as BSPagination } from "react-bootstrap";

const Pagination = ({ filter, setFilter, totalCount }) => {
    const totalPages = Math.ceil(totalCount / filter.limit);

    const changePage = (newPage) => {
        setFilter((prev) => ({ ...prev, page: newPage }));
    };

    return (
        <BSPagination className="justify-content-center mt-3">
            <BSPagination.Prev 
                onClick={() => changePage(filter.page - 1)}
                disabled={filter.page === 0}
            />

            <BSPagination.Item active>
                Strana {filter.page + 1} z {totalPages}
            </BSPagination.Item>

            <BSPagination.Next 
                onClick={() => changePage(filter.page + 1)}
                disabled={filter.page >= totalPages - 1}
            />
        </BSPagination>
    );
};

export default Pagination;
